"use client";

/**
 * Prompt compose: a composer card grows out of a thin line, the prompt types
 * itself, then a pointer glides to the send button and clicks it.
 *
 * Written by Better Design. Painted from the theme prop, so the line, the
 * caret and the send button take the product's primary colour.
 */
import { loadFont } from "@remotion/google-fonts/Inter";
import { AbsoluteFill, interpolate, useCurrentFrame, useVideoConfig } from "remotion";
import { Caret, easings, mix, pickFont, progress, type SoundCue, SoundTrack, typed, typingCues, type VideoTheme, useVideoTheme, withAlpha } from "@/lib/bd-video";

const { fontFamily: INTER } = loadFont("normal", { weights: ["400", "500"], subsets: ["latin"] });

const LINE_FRAMES = 14;
const GROW_AT = 12;
const GROW_FRAMES = 18;
const TYPE_AT = 38;
/** Frames the typing takes at most, however long the prompt is. */
const TYPE_BUDGET = 48;
const W = 1400;
const H = 340;
const TOP = (1080 - H) / 2;
const LEFT = (1920 - W) / 2;
const BTN = 88;
const BTN_X = LEFT + W - 36 - BTN / 2;
const BTN_Y = TOP + H - 32 - BTN / 2;
const DEFAULT_PROMPT = "Draft a launch note for the new sharing feature, short and friendly";

/** How fast the prompt types, and the frames where typing ends, the pointer sets off and the click lands. */
function timing(prompt: string, fps: number) {
  const cps = Math.max(30, (prompt.length / TYPE_BUDGET) * fps);
  const typeEnd = TYPE_AT + Math.ceil((prompt.length / cps) * fps);
  const pointerAt = typeEnd + 6;
  return { cps, pointerAt, clickAt: pointerAt + 24 };
}

/** The sound of a PromptCompose: the card opening, every key, the click on send and the check landing. */
export function promptComposeCues(prompt: string = DEFAULT_PROMPT, fps = 30): SoundCue[] {
  const { cps, clickAt } = timing(prompt, fps);
  return [
    { sfx: "pop-soft", at: GROW_AT + 4 },
    ...typingCues(prompt, TYPE_AT + fps / cps, cps, fps),
    { sfx: "click", at: clickAt },
    { sfx: "pop-soft", at: clickAt + 7, gain: -4 },
  ];
}

export interface PromptComposeProps {
  /** The prompt that types itself into the card. */
  prompt?: string;
  /** Grey text in the empty card. */
  placeholder?: string;
  theme?: Partial<VideoTheme>;
  /** A CSS font family the project has loaded. Defaults to the theme's face, then Inter. */
  font?: string;
  /** Play the shot's own sound cues. Leave off inside a film that plays every scene's cues in one SoundTrack. */
  sound?: boolean;
}

const clamp = { extrapolateLeft: "clamp", extrapolateRight: "clamp" } as const;

function Pointer({ theme }: { theme: VideoTheme }) {
  return (
    <svg width={52} height={60} viewBox="0 0 26 30" style={{ filter: `drop-shadow(0 6px 10px ${withAlpha(theme.foreground, 0.3)})` }}>
      <path d="M3 2 L3 24 L9 18.5 L13 27.5 L17 25.8 L13.2 17 L21.5 17 Z" fill={theme.foreground} stroke={theme.background} strokeWidth={1.8} strokeLinejoin="round" />
    </svg>
  );
}

/** A composer card grows, takes a prompt and is sent with one click. */
export function PromptCompose({
  prompt = DEFAULT_PROMPT,
  placeholder = "Ask anything",
  theme: themeOverride,
  font,
  sound = false,
}: PromptComposeProps) {
  const theme = useVideoTheme(themeOverride);
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();
  const family = pickFont(font, theme, INTER);

  const { cps, pointerAt, clickAt } = timing(prompt, fps);

  const line = easings.out(progress(frame, 0, LINE_FRAMES));
  const grow = easings.out(progress(frame, GROW_AT, GROW_FRAMES));
  const width = W * line;
  const height = 4 + (H - 4) * grow;
  const content = progress(frame, GROW_AT + GROW_FRAMES * 0.6, 8);

  const value = typed(prompt, frame, TYPE_AT, fps, cps);
  const typing = frame >= TYPE_AT && value.length < prompt.length;
  const armed = easings.out(progress(frame, TYPE_AT, 8));
  const sent = easings.out(progress(frame, clickAt + 2, 10));

  const glide = easings.inOut(progress(frame, pointerAt, 24));
  const px = interpolate(glide, [0, 1], [1880, BTN_X - 8]);
  const py = interpolate(glide, [0, 1], [1120, BTN_Y - 6]) - Math.sin(glide * Math.PI) * 70;
  // After the click the pointer eases off the button so the check reads.
  const leave = easings.out(progress(frame, clickAt + 8, 16));
  const pressCurve = interpolate(frame, [clickAt, clickAt + 3, clickAt + 10], [0, 1, 0], clamp);
  const ring = progress(frame, clickAt + 2, 18);

  const iconColor = mix(theme.mutedForeground, theme.primaryForeground, armed);

  return (
    <AbsoluteFill style={{ background: theme.background, fontFamily: family, overflow: "hidden" }}>
      {sound ? <SoundTrack cues={promptComposeCues(prompt, fps)} music={false} /> : null}
      <div
        style={{
          position: "absolute",
          left: 960 - width / 2,
          top: 540 - height / 2,
          width,
          height,
          borderRadius: Math.min(theme.radius * 2.4, height / 2),
          background: theme.card,
          border: grow > 0.2 ? `1px solid ${withAlpha(theme.border, grow)}` : "none",
          boxShadow: `0 40px 90px -40px ${withAlpha(theme.foreground, 0.25 * grow)}`,
          overflow: "hidden",
        }}
      >
        <div style={{ position: "absolute", inset: 0, background: theme.primary, opacity: 1 - grow }} />
        <div style={{ position: "absolute", inset: 0, opacity: content, padding: "44px 52px", fontSize: 46, lineHeight: 1.36, letterSpacing: "-0.012em", color: theme.cardForeground }}>
          {value ? value : <span style={{ color: theme.mutedForeground }}>{placeholder}</span>}
          {frame < clickAt ? <Caret color={theme.ring} height={50} solid={typing} /> : null}
        </div>
        <div style={{ position: "absolute", left: 40, bottom: 34, width: 72, height: 72, borderRadius: 36, border: `1.5px solid ${theme.border}`, opacity: content, display: "flex", alignItems: "center", justifyContent: "center" }}>
          <svg width={30} height={30} viewBox="0 0 24 24" fill="none" stroke={theme.mutedForeground} strokeWidth={2.2} strokeLinecap="round">
            <path d="M12 5v14M5 12h14" />
          </svg>
        </div>
      </div>

      <div
        style={{
          position: "absolute",
          left: BTN_X - BTN / 2,
          top: BTN_Y - BTN / 2,
          width: BTN,
          height: BTN,
          borderRadius: BTN / 2,
          background: theme.muted,
          overflow: "hidden",
          opacity: content,
          transform: `scale(${1 - 0.12 * pressCurve})`,
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          boxShadow: `0 12px 28px -12px ${withAlpha(theme.primary, 0.7 * armed)}`,
        }}
      >
        <div style={{ position: "absolute", inset: 0, background: theme.primary, opacity: armed }} />
        <svg width={40} height={40} viewBox="0 0 24 24" fill="none" stroke={iconColor} strokeWidth={2.4} strokeLinecap="round" strokeLinejoin="round" style={{ position: "absolute", opacity: 1 - sent, transform: `translateY(${-sent * 10}px)` }}>
          <path d="M12 19V5M6 11l6-6 6 6" />
        </svg>
        <svg width={40} height={40} viewBox="0 0 24 24" fill="none" stroke={theme.primaryForeground} strokeWidth={2.6} strokeLinecap="round" strokeLinejoin="round" style={{ position: "absolute", opacity: sent }}>
          <path d="M5 12.5l4.5 4.5L19 7" strokeDasharray="22" strokeDashoffset={22 * (1 - sent)} />
        </svg>
      </div>
      {ring > 0 && ring < 1 ? (
        <div
          style={{
            position: "absolute",
            left: BTN_X - BTN / 2,
            top: BTN_Y - BTN / 2,
            width: BTN,
            height: BTN,
            borderRadius: BTN / 2,
            border: `3px solid ${theme.primary}`,
            opacity: 0.6 * (1 - ring),
            transform: `scale(${1 + easings.out(ring) * 0.9})`,
          }}
        />
      ) : null}

      {glide > 0 ? (
        <div style={{ position: "absolute", left: px + leave * 70, top: py + leave * 64, transform: `scale(${1 - 0.14 * pressCurve})`, transformOrigin: "3px 2px" }}>
          <Pointer theme={theme} />
        </div>
      ) : null}
    </AbsoluteFill>
  );
}
